    closed_count = n
    direction = 1  # +1 for right, -1 for left
    passes = 0
    last = None
    while closed_count > 0:
        passes += 1
        stage_open = True
        open_rem = r
        skip_rem = 0
        i = 1 if direction == 1 else n
        while True:
            if 1 <= i <= n:
                if closed[i]:
                    if stage_open:
