                        closed[i] = False
                        closed_count -= 1
                        last = i
                        open_rem -= 1
                        if open_rem == 0:
                            stage_open = False
                            skip_rem = s
                    else:
                        # skip this closed locker
                        skip_rem -= 1
                        if skip_rem == 0:
                            stage_open = True
                            open_rem = r
                i += direction
            else:
                break
        direction *= -1
    return last, passes
